def _check_name(entity, entity_type):
    """Check whether the name is valid.

    First check if the name is missing, and then check if it is a qualified
    string type, finally check if the string is empty. For all checks, it
    would raise a ParseError with the corresponding message.

    Args:
        entity: a string type object to be checked.
        entity_type: a string that shows the type of entities to check, usually
            `Compound` or 'Reaction'.
    """
    if not entity:
        raise ParseError('{} name is missing.'.format(entity_type))
    if not isinstance(entity, str):
        raise ParseError('{} name is not a string.'.format(entity_type))
    if not entity.strip():
        raise ParseError('{} name is empty.'.format(entity_type))


